	@ParameterizedTest
	@ValueSource(ints = { 640, 960 })
	void bothCatalogEnvelopesPreserveExistingPackBytes(int extent) throws Exception {
		byte[] pack = pack(2);
		byte[] legacy = LmdbBackupCatalogTestSupport.wrap(pack, extent);
		byte[] compressed = compressed(pack, extent);
		assertTrue(LmdbBackupOutbox.validateCatalogValue(ByteBuffer.wrap(legacy)));
		assertTrue(LmdbBackupOutbox.validateCatalogValue(ByteBuffer.wrap(compressed)));
		assertArrayEquals(pack, LmdbBackupCatalogTestSupport.unpack(legacy));
		assertArrayEquals(pack, LmdbBackupCatalogTestSupport.unpack(compressed));
		ByteBuffer positioned = ByteBuffer.allocate(extent + 32).order(ByteOrder.LITTLE_ENDIAN);
		positioned.position(17).put(compressed).limit(extent + 17).position(17);
		assertTrue(LmdbBackupOutbox.validateCatalogValue(positioned),
				"Validation must respect the native view's position and fixed envelope length");
	}

	@Test
	void crossStageCompressionFitsFiveActualFramesInEitherReservation() throws Exception {
		byte[] pack = pack(5);
		assertTrue(pack.length > LmdbBackupCatalogTestSupport.packCapacity(960));
		for (int extent : new int[] { 640, 960 }) {
			byte[] encoded = compressed(pack, extent);
			assertTrue(LmdbBackupOutbox.validateCatalogValue(ByteBuffer.wrap(encoded)));
			assertArrayEquals(pack, LmdbBackupCatalogTestSupport.unpack(encoded));
		}
	}

